package perms

import (
	"fmt"
	"testing"
)

func TestPermutationsOne(t *testing.T) {
	perms := Permutations([]int{1})
	if len(perms) != 1 {
		t.Fatalf("want 1 permutation, got %d", len(perms))
	}
}

func TestPermutationsTwo(t *testing.T) {
	perms := Permutations([]int{1, 2})
	if len(perms) != 2 {
		t.Fatalf("want 2 permutations, got %d", len(perms))
	}
}

func TestPermutationsThree(t *testing.T) {
	perms := Permutations([]int{1, 2, 3})
	if len(perms) != 6 {
		t.Fatalf("want 6 permutations, got %d", len(perms))
	}
}

func TestPermutationsEmpty(t *testing.T) {
	perms := Permutations([]int{})
	if len(perms) != 1 {
		t.Fatalf("want 1 (empty permutation), got %d", len(perms))
	}
}

func TestPermutationsUnique(t *testing.T) {
	perms := Permutations([]int{1, 2, 3})
	seen := make(map[string]bool)
	for _, p := range perms {
		key := fmt.Sprintf("%v", p)
		if seen[key] {
			t.Fatalf("duplicate permutation: %v", p)
		}
		seen[key] = true
	}
}

