Implement Permutations in perms.go using swap-based backtracking.

func Permutations(nums []int) [][]int
  // Work on a copy of nums to avoid mutating the input.
  // Backtrack(start int):
  //   if start == len(nums): copy nums into result
  //   for i from start to len(nums)-1:
  //     swap nums[start] and nums[i]
  //     backtrack(start+1)
  //     swap back (restore)
  // Empty input yields [[]] — one empty permutation.

All 5 tests in perms_test.go must pass.
